    const deg = new Int32Array(nV + 1);
    for (let e = 0; e < nB; e++) { deg[bFrom[e] + 1]++; deg[bTo[e] + 1]++; }
    for (let i = 0; i < nV; i++) deg[i + 1] += deg[i];
