  const base = { plane:new THREE.Color(css('--plane')), cyl:new THREE.Color(css('--cyl')), cone:new THREE.Color(css('--cone')), sphere:new THREE.Color(css('--sphere')) };
  const planeC = base.plane;
  const faceCols = faceTypes.map((t, i) => hashColor(i, base[t] || planeC, t === 'plane' ? 0.22 : 0.12));
  for(let t = 0; t < nT; t++){
    const c = faceCols[triFace[t]] || planeC;
    for(let j = 0; j < 3; j++){
      const v = T[t*3+j];
      pos[t*9+j*3] = P[v*3]; pos[t*9+j*3+1] = P[v*3+1]; pos[t*9+j*3+2] = P[v*3+2];
      colF[t*9+j*3] = c.r; colF[t*9+j*3+1] = c.g; colF[t*9+j*3+2] = c.b;
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.BufferAttribute(colF, 3));
  g.computeVertexNormals();
  const matFaces = new THREE.MeshStandardMaterial({ vertexColors:true, roughness:0.55, metalness:0.08, flatShading:true, side:THREE.DoubleSide, polygonOffset:true, polygonOffsetFactor:1, polygonOffsetUnits:1 });
  const faces = new THREE.Mesh(g, matFaces); faces.name = 'faces';
  const matMesh = new THREE.MeshStandardMaterial({ color:new THREE.Color(css('--plane')), roughness:0.6, metalness:0.05, flatShading:true, side:THREE.DoubleSide, polygonOffset:true, polygonOffsetFactor:1, polygonOffsetUnits:1 });
  const meshSolid = new THREE.Mesh(g, matMesh); meshSolid.name = 'meshSolid';
