  const snapCfg = () => (host && host.snap ? host.snap() : { grid: true, obj: true, size: 1, sizes: [{ v: 1, label: '1 mm' }] });
  // the sketch grid as Advanced draws it: the snap size, or a multiple of it when zoomed out
